// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type DietRulesProps = Record<string, any>;

const DietRules: React.FC<DietRulesProps> = ({
  backgroundColor = "#0F172A", // Dark Slate
  transparentBackground = false,
  durationInSeconds = 8,
  title = "Diet Rules",
  items = [
    "Count every single calorie",
    "Never eat after 8 PM",
    "Avoid all carbohydrates",
  ],
  finalText = "You understand YOUR body",
  accentColor = "#10B981", // Emerald
  textColor = "#F8FAFC", // Off-white
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Responsive calculations
  const isPortrait = height > width;
  const paddingX = width * 0.08;
  const titleFontSize = isPortrait ? width * 0.12 : height * 0.12;
  const itemFontSize = isPortrait ? width * 0.055 : height * 0.055;
  const finalFontSize = isPortrait ? width * 0.1 : height * 0.1;
  const iconSize = itemFontSize * 1.5;

  // Core Timings
  const itemStagger = 20;
  const checkDelay = 25; // How long after an item appears before it gets checked
  
  // Calculate when the dissolve phase should start based on number of items
  // Add a 40-frame pause after the last checkmark
  const lastItemCheckFrame = (items.length - 1) * itemStagger + checkDelay + 20; 
  const dissolveStartFrame = Math.max(120, lastItemCheckFrame + 40);

  // Animations for the entire checklist container
  const checklistDissolveOpacity = interpolate(
    frame,
    [dissolveStartFrame, dissolveStartFrame + 20],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const checklistDissolveY = interpolate(
    frame,
    [dissolveStartFrame, dissolveStartFrame + 20],
    [0, -100],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Title Animations
  const titleEntranceProgress = spring({
    frame,
    fps,
    config: { damping: 12, mass: 1.2 },
  });
  
  const titleY = interpolate(titleEntranceProgress, [0, 1], [-50, 0]);
  const titleOpacity = interpolate(titleEntranceProgress, [0, 1], [0, 1]);

  // Final Text Animations
  const finalStartFrame = dissolveStartFrame + 15;
  const finalEntranceProgress = spring({
    frame: frame - finalStartFrame,
    fps,
    config: { damping: 14, mass: 1.5 },
  });

  const finalScale = interpolate(finalEntranceProgress, [0, 1], [0.8, 1]);
  const finalOpacity = interpolate(finalEntranceProgress, [0, 1], [0, 1]);

  // Helper to split and highlight capitalized words
  const renderFinalText = (text: string) => {
    return text.split(" ").map((word, i) => {
      // Very simple heuristic: Highlight fully capitalized words longer than 1 character
      const isHighlight = word === word.toUpperCase() && word.length > 1;
      return (
        <span
          key={i}
          style={{
            color: isHighlight ? accentColor : textColor,
            marginRight: "0.25em",
            display: "inline-block",
            transition: "none",
          }}
        >
          {word}
        </span>
      );
    });
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: textColor,
        transition: "none",
      }}
    >
      {/* SCENE 1 & 2: Checklist */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "flex-start",
          paddingLeft: paddingX,
          paddingRight: paddingX,
          opacity: checklistDissolveOpacity,
          transform: `translateY(${checklistDissolveY}px)`,
          transition: "none",
        }}
      >
        <h1
          style={{
            fontSize: titleFontSize,
            fontWeight: 800,
            marginBottom: height * 0.05,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            margin: `0 0 ${height * 0.05}px 0`,
            lineHeight: 1.1,
            color: accentColor,
            transition: "none",
          }}
        >
          {title}
        </h1>

        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: height * 0.03,
            width: "100%",
            transition: "none",
          }}
        >
          {items.map((item, index) => {
            const itemAppearFrame = 20 + index * itemStagger;
            const checkFrame = itemAppearFrame + checkDelay;

            // Entrance Spring
            const itemAppearProgress = spring({
              frame: frame - itemAppearFrame,
              fps,
              config: { damping: 14, mass: 1 },
            });

            const itemY = interpolate(itemAppearProgress, [0, 1], [40, 0]);
            const itemOpacity = interpolate(itemAppearProgress, [0, 1], [0, 1]);

            // Checkmark SVG Draw
            const checkDashOffset = interpolate(
              frame,
              [checkFrame, checkFrame + 15],
              [26, 0],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );
            
            // Checkmark Pop
            const checkScaleProgress = spring({
              frame: frame - checkFrame,
              fps,
              config: { damping: 10, mass: 0.6 },
            });
            const checkScale = interpolate(checkScaleProgress, [0, 1], [0.5, 1], {
              extrapolateLeft: "clamp",
            });

            // Strike-through line logic (optional cool visual)
            const strikeProgress = spring({
              frame: frame - checkFrame - 10, // slightly after check
              fps,
              config: { damping: 16 },
            });
            const textOpacity = interpolate(strikeProgress, [0, 1], [1, 0.4]);

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  alignItems: "center",
                  opacity: itemOpacity,
                  transform: `translateY(${itemY}px)`,
                  transition: "none",
                }}
              >
                {/* SVG Checkbox */}
                <div
                  style={{
                    width: iconSize,
                    height: iconSize,
                    marginRight: width * 0.04,
                    flexShrink: 0,
                    position: "relative",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    transition: "none",
                  }}
                >
                  {/* Base Box */}
                  <svg
                    width="100%"
                    height="100%"
                    viewBox="0 0 32 32"
                    style={{ position: "absolute", transition: "none" }}
                  >
                    <rect
                      x="4"
                      y="4"
                      width="24"
                      height="24"
                      rx="6"
                      fill="transparent"
                      stroke={textColor}
                      strokeWidth={3}
                      opacity={0.3}
                      style={{ transition: "none" }}
                    />
                  </svg>
                  
                  {/* Animated Check */}
                  <svg
                    width="100%"
                    height="100%"
                    viewBox="0 0 32 32"
                    style={{
                      position: "absolute",
                      transform: `scale(${checkScale})`,
                      opacity: frame >= checkFrame ? 1 : 0,
                      transition: "none",
                    }}
                  >
                    <path
                      d="M 9 16 L 14 21 L 24 9"
                      fill="transparent"
                      stroke={accentColor}
                      strokeWidth={4.5}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeDasharray="26"
                      strokeDashoffset={checkDashOffset}
                      style={{ transition: "none" }}
                    />
                  </svg>
                </div>

                {/* Text Item */}
                <span
                  style={{
                    fontSize: itemFontSize,
                    fontWeight: 100,
                    lineHeight: 1.3,
                    opacity: textOpacity,
                    position: "relative",
                    transition: "none",
                  }}
                >
                  {item}
                  {/* Strikethrough Line overlay */}
                  <div
                    style={{
                      position: "absolute",
                      left: 0,
                      top: "50%",
                      height: 3,
                      backgroundColor: textColor,
                      width: `${strikeProgress * 100}%`,
                      transform: "translateY(-50%)",
                      opacity: 0.6,
                      transition: "none",
                    }}
                  />
                </span>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>

      {/* SCENE 3: Final Statement */}
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          padding: paddingX * 1.5,
          pointerEvents: "none", // ensure it doesn't block interactions if embedded
          transition: "none",
        }}
      >
        <h2
          style={{
            fontSize: finalFontSize,
            fontWeight: 800,
            textAlign: "center",
            lineHeight: 1.2,
            opacity: finalOpacity,
            transform: `scale(${finalScale})`,
            margin: 0,
            textWrap: "balance",
            transition: "none",
          }}
        >
          {renderFinalText(finalText)}
        </h2>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default DietRules;